async (page) => {
  await page.getByRole('textbox').first().fill('');
  await page.waitForTimeout(1500);
  const seen = new Map();
  for (let i = 0; i < 200; i++) {
    const rows = await page.evaluate(() => [...document.querySelectorAll('vaadin-grid tr')].map(r => [...r.querySelectorAll('td')].map(c => c.innerText.trim())).filter(r => r.length >= 5));
    rows.forEach(r => seen.set(r[2], r));
    const done = await page.evaluate(() => { const g = document.querySelector('vaadin-grid'); const before = g.scrollTop; g.scrollTop += 400; return g.scrollTop === before; });
    await page.waitForTimeout(150);
    if (done) break;
  }
  const all = [...seen.values()];
  const pvh = all.filter(r => r[4].includes('Phillips'));
  return {total: all.length, pvh: pvh.length, lost: pvh.filter(r => r[3] === 'Closed (lost)').map(r=>r[2])};
}

