  const seen = new Map();
  const grid = page.locator('vaadin-grid').first();
  await grid.hover();
  for (let i = 0; i < 300; i++) {
    const rows = await page.getByRole('row').allInnerTexts();
    rows.forEach(t => { const p = t.split('\t').map(s=>s.trim()); if (p.length>=5) seen.set(p[2], p); });
    const n = seen.size;
    await page.mouse.wheel(0, 500);
    await page.waitForTimeout(250);
    const rows2 = await page.getByRole('row').allInnerTexts();
    rows2.forEach(t => { const p = t.split('\t').map(s=>s.trim()); if (p.length>=5) seen.set(p[2], p); });
    if (seen.size === n && i > 3) break;
  }
  const all = [...seen.values()];
  const pvh = all.filter(r => r[4].includes('Phillips'));
  return {total: all.length, pvh: pvh.length, lost: pvh.filter(r => r[3] === 'Closed (lost)').map(r=>r[2])};
}

