async (page) => {
  const seen = new Map();
  await page.locator('vaadin-grid').first().hover();
  const grab = async () => {
    const s = await page.getByRole('treegrid').ariaSnapshot();
    for (const m of s.matchAll(/row "([^"]*)"/g)) seen.set(m[1], 1);
  };
  for (let i = 0; i < 300; i++) {
    await grab();
    const n = seen.size;
    await page.mouse.wheel(0, 600);
    await page.waitForTimeout(300);
    await grab();
    if (seen.size === n && i > 3) break;
  }
  const all = [...seen.keys()].filter(k=>k.includes('@'));
  const pvh = all.filter(r => r.includes('Phillips Van Heusen'));
  return {total: all.length, pvh: pvh.length, lost: pvh.filter(r => r.includes('Closed (lost)'))};
}

